lab.solution:
class RunMarker:
    def __init__(self):
        self.active = False

    def __enter__(self):
        self.active = True
        return self

    def __exit__(self, exc_type, exc, traceback):
        self.active = False
        return False

marker = RunMarker()
for fail in [False, True]:
    try:
        with marker:
            print(marker.active)
            if fail:
                raise ValueError('practice failure')
    except ValueError:
        print('caught')
    print(marker.active)
